function messagesFromEnOverlay(overlay: Record<string, unknown>): typeof en {
  return mergeDeep(
    structuredClone(en) as unknown as Record<string, unknown>,
    overlay,
  ) as typeof en;
}

function localeFromOverlays(
  locale: Locale,
  baseOverlay: Record<string, unknown>,
  premiumOverlay: Record<string, unknown>,
): typeof en {
  const withPremium = mergeDeep(baseOverlay, premiumOverlay);
  const marketingHome = MARKETING_HOME_OVERLAYS[locale] ?? {};
  const siteChrome = SITE_CHROME_OVERLAYS[locale] ?? {};
  const faqOverlay = FAQ_LOCALE_OVERLAYS[locale] ?? {};
  const messageDraftsOverlay = RECRUITER_MESSAGE_DRAFTS_OVERLAYS[locale] ?? {};
  const personaHubRecruiterOverlay = PERSONA_HUB_RECRUITER_OVERLAYS[locale] ?? {};
  const talentRadarAtsDemoOverlay = TALENT_RADAR_ATS_DEMO_OVERLAYS[locale] ?? {};
  const profilePipelineTrustOverlay = PROFILE_PIPELINE_TRUST_OVERLAYS[locale] ?? {};
  const offerPlacementCalendarOverlay = OFFER_READINESS_PLACEMENT_CALENDAR_OVERLAYS[locale] ?? {};
  const investorRoomOverlay = INVESTOR_ROOM_OVERLAYS[locale] ?? {};
  const investorDataRoomOverlay = INVESTOR_DATA_ROOM_OVERLAYS[locale as keyof typeof INVESTOR_DATA_ROOM_OVERLAYS] ?? {};
  return messagesFromEnOverlay(
    mergeDeep(
      mergeDeep(
        mergeDeep(
          mergeDeep(mergeDeep(withPremium, marketingHome), siteChrome),
          { faq: faqOverlay },
        ),
        messageDraftsOverlay,
      ),
      mergeDeep(
        personaHubRecruiterOverlay,
        mergeDeep(
          talentRadarAtsDemoOverlay,
          mergeDeep(
            mergeDeep(profilePipelineTrustOverlay, offerPlacementCalendarOverlay),
            mergeDeep(investorRoomOverlay, investorDataRoomOverlay),
          ),
        ),
      ),
    ),
  );
}

const es = localeFromOverlays("es", esOverlay, premiumEsOverlay);
const it = localeFromOverlays("it", itOverlay, premiumItOverlay);
const fr = localeFromOverlays("fr", frOverlay, premiumFrOverlay);
const de = localeFromOverlays("de", deOverlay, premiumDeOverlay);
const zh = localeFromOverlays("zh", zhOverlay, premiumZhOverlay);
const ar = localeFromOverlays("ar", arOverlay, premiumArOverlay);
const ja = localeFromOverlays("ja", jaOverlay, premiumJaOverlay);

export { en, pl };

export const dictionaries: Record<Locale, typeof en> = {
  en,
  pl: pl as typeof en,
  es,
  it,
  fr,
  de,
  zh,
  ar,
  ja,
};

export function detectBrowserLocale(): Locale {
  if (typeof navigator === "undefined") return "en";
  const raw = navigator.language?.toLowerCase() ?? "en";
  const primary = raw.split("-")[0] ?? "en";
  if (raw.startsWith("zh") || primary === "zh") return "zh";
  if (raw.startsWith("ar") || primary === "ar") return "ar";
  const byPrimary: Record<string, Locale> = {
    pl: "pl",
    es: "es",
    it: "it",
    fr: "fr",
    de: "de",
    ja: "ja",
  };
  return byPrimary[primary] ?? "en";
}

export function getNestedValue(obj: Record<string, unknown>, path: string): string {
  const parts = path.split(".");
  let current: unknown = obj;
  for (const part of parts) {
    if (current == null || typeof current !== "object") return path;
    current = (current as Record<string, unknown>)[part];
  }
  return typeof current === "string" ? current : path;
}

export function translate(locale: Locale, key: TranslationKey): string {
  return getNestedValue(dictionaries[locale] as unknown as Record<string, unknown>, key);
}
